if (runwayText == "YES") {
  runwayText = "<div style='text-align:center;'><span style='background-color:" + colorYes + ";color:#fff;font-weight:bold;padding:4px 10px;border-radius:12px;display:inline-block;'>" + runwayText + "</span></div>";
} else if (runwayText == "NO") {
  runwayText = "<div style='text-align:center;'><span style='background-color:" + colorNo + ";color:#fff;font-weight:bold;padding:4px 10px;border-radius:12px;display:inline-block;'>" + runwayText + "</span></div>";
}

